package org.hermesmobile.app

import kotlinx.serialization.json.*
import org.hermesmobile.app.data.*
import org.junit.Assert.*
import org.junit.Test

class CustomEndpointProbeTest {
    private val target=ManagementTarget("a".repeat(64),"https://host.test/prefix/","worker","password · fixture")
    private fun j(s:String)=Json.parseToJsonElement(s).jsonObject
    private val snapshot get()=CustomEndpointSnapshot.parse(j("""{"endpoints":[],"current":{"provider":"old","model":"old","base_url":"https://old.test"}}"""),j("{}"),target,"home-fixture")
    private fun draft(key:CustomEndpointKey=CustomEndpointKey.Keep,secret:String="",url:String="https://endpoint.test/v1",model:String="private-model",mode:String?=null)=CustomEndpointDraft("new-id","Private endpoint",url,model,key,secret,mode,8192,false,true,listOf("ignored-extra"))
    @Test fun keepAndClearNeverReuseStoredCredentialsOrSendSaveOnlyFields() {for(key in listOf(CustomEndpointKey.Keep,CustomEndpointKey.Clear)) {val request=CustomEndpointProbeRequest(snapshot,draft(key));assertEquals(setOf("name","base_url","model","api_mode"),request.body().keys);assertEquals(JsonPrimitive(""),request.body()["api_mode"]);assertFalse(request.fresh)}}
    @Test fun freshCredentialAndExplicitModeAreFrozenExactly() {val request=CustomEndpointProbeRequest(snapshot,draft(CustomEndpointKey.Fresh," fresh-probe-fixture ",mode="codex_responses"));assertEquals(JsonPrimitive("fresh-probe-fixture"),request.body()["api_key"]);assertEquals(JsonPrimitive("codex_responses"),request.body()["api_mode"]);assertTrue(request.fresh)}
    @Test fun resultBindingIncludesEveryOutboundFieldAndFreshCredentialChoice() {val d=draft();val r=CustomEndpointProbeRequest(snapshot,d);assertTrue(r.same(d));assertFalse(r.same(draft(url="https://other.test")));assertFalse(r.same(draft(model="other-model")));assertFalse(r.same(draft(mode="anthropic_messages")));assertFalse(r.same(draft(CustomEndpointKey.Fresh,"other-key-fixture")));assertTrue(r.same(draft(CustomEndpointKey.Clear)))}
    @Test fun typedNegativeReportsAreAcknowledgedButStringFlagsAreRejected() {val request=CustomEndpointProbeRequest(snapshot,draft());val ack=request.acknowledge(j("""{"ok":false,"reachable":true}"""));assertFalse(ack.ok);assertTrue(ack.reachable);for(raw in listOf("{}","{\"ok\":true}","{\"ok\":\"false\",\"reachable\":true}","{\"ok\":true,\"reachable\":1}")) assertTrue(runCatching {request.acknowledge(j(raw))}.isFailure)}
    @Test fun malformedOptionalDetailsDoNotEraseMandatoryFlags() {val request=CustomEndpointProbeRequest(snapshot,draft());val raw=j("""{"ok":true,"reachable":true,"models":17,"message":"private-response-fixture"}""");assertTrue(request.acknowledge(raw).ok);assertNull(CustomEndpointProbeDetails.parse(raw))}
    @Test fun optionalAliasDetailsRemainImmutablePrivateDataWithoutAutomaticAdoption() {val details=CustomEndpointProbeDetails.parse(j("""{"models":["alias"],"model_details":[{"id":"alias","canonical_model":"canonical-private","reasoning_effort":"high"}],"resolved_base_url":"https://resolved.test/v1","transport_checked":"codex_responses","message":"private-response-fixture"}"""))!!;assertEquals("canonical-private",details.details.single().canonicalModel);assertEquals("high",details.details.single().reasoningEffort);assertEquals("https://resolved.test/v1",details.resolvedBaseUrl);assertTrue(runCatching {(details.models as MutableList).clear()}.isFailure);assertTrue(runCatching {(details.details as MutableList).clear()}.isFailure);assertFalse(details.toString().contains("private"));assertFalse(details.details.single().toString().contains("private"))}
    @Test fun malformedDuplicateAndOversizedOptionalDataRefusesWithoutTruncation() {for(raw in listOf("{\"models\":[\"x\",\"x\"]}","{\"models\":[17]}","{\"model_details\":[{\"id\":\"x\",\"canonical_model\":17}]}","{\"message\":\""+"x".repeat(16385)+"\"}")) assertNull(CustomEndpointProbeDetails.parse(j(raw)))}
    @Test fun summariesAndStringRepresentationsNeverExposeOutboundPrivateValues() {val request=CustomEndpointProbeRequest(snapshot,draft(CustomEndpointKey.Fresh,"fresh-probe-private-fixture"));val ack=request.acknowledge(j("""{"ok":false,"reachable":false,"message":"private-response-fixture"}"""));val all=listOf(request.toString(),request.summary().toString(),ack.summary(request).toString());for(value in all) for(secret in listOf("fresh-probe-private-fixture","endpoint.test","private-model","Private endpoint","private-response-fixture")) assertFalse(value.contains(secret));assertEquals(JsonPrimitive(true),ack.summary(request)["listener_network_scope"])}
}
